package org.cleantv.launcher;
import android.app.*;import android.os.*;import android.content.*;import android.graphics.*;import android.graphics.drawable.*;import android.net.Uri;import android.view.*;import android.widget.*;import org.json.*;import java.util.*;import java.io.*;

/** Local editorial catalogue and explicit user feedback; no account or viewing-history access. */
public class PickActivity extends Activity {
 SharedPreferences prefs; ArrayList<JSONObject> catalogue=new ArrayList<>(),eligible=new ArrayList<>();JSONObject current;FrameLayout root;int cursor=0;String lastId,lastKey;Object lastValue;boolean ready=false;
 int dp(float n){return (int)(n*getResources().getDisplayMetrics().density+.5f);} String s(JSONObject o,String key){return o.optString(key);}
 String pref(String key,String value){return prefs.getString(key,value);} int limit(){return prefs.getInt("limit",0);}
 GradientDrawable bg(int color,int radius){GradientDrawable d=new GradientDrawable();d.setColor(color);d.setCornerRadius(dp(radius));return d;}
 void put(View view,int w,int h,int x,int y){FrameLayout.LayoutParams p=new FrameLayout.LayoutParams(w<0?w:dp(w),h<0?h:dp(h));p.leftMargin=dp(x);p.topMargin=dp(y);root.addView(view,p);}
 TextView label(String value,int size,int color,int w,int h,int x,int y){TextView t=new TextView(this);t.setText(value);t.setTextSize(size);t.setTextColor(color);t.setFontFeatureSettings("kern");t.setIncludeFontPadding(false);put(t,w,h,x,y);return t;}
 Button button(String title,int w,int x,int y,Runnable action){Button b=new Button(this);b.setText(title);b.setAllCaps(false);b.setTextSize(13);b.setPadding(dp(10),0,dp(10),0);b.setTextColor(0xffe7ebf2);b.setBackground(bg(0xff252c38,10));b.setStateListAnimator(null);b.setOnFocusChangeListener((v,f)->{b.setTextColor(f?0xff101620:0xffe7ebf2);b.setBackground(bg(f?0xfff4f6fa:0xff252c38,10));v.animate().scaleX(f?1.025f:1).scaleY(f?1.025f:1).setDuration(160).start();});b.setOnClickListener(v->action.run());put(b,w,40,x,y);return b;}
 @Override public void onCreate(Bundle state){super.onCreate(state);getWindow().getDecorView().setSystemUiVisibility(5894);prefs=getSharedPreferences("picks",0);try{InputStream in=getResources().openRawResource(R.raw.picks);ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] bytes=new byte[4096];int n;while((n=in.read(bytes))!=-1)out.write(bytes,0,n);in.close();JSONArray a=new JSONArray(out.toString("UTF-8"));for(int i=0;i<a.length();i++)catalogue.add(a.getJSONObject(i));ready=true;}catch(Exception e){Toast.makeText(this,"The local catalogue could not load",Toast.LENGTH_LONG).show();}refresh();}
 void refresh(){eligible.clear();long now=System.currentTimeMillis();for(JSONObject o:catalogue){String id=s(o,"id");if(!prefs.getBoolean("service_"+s(o,"provider"),true)||prefs.getBoolean("watched_"+id,false)||prefs.getBoolean("dislike_"+id,false)||prefs.getLong("skip_"+id,0)>now)continue;if(PickRules.matches(s(o,"language"),o.optInt("minutes"),s(o,"mood"),s(o,"kind"),pref("language","Any language"),limit(),pref("mood","Any mood"),pref("kind","Anything")))eligible.add(o);}Collections.sort(eligible,(a,b)->Integer.compare(score(b),score(a)));cursor=0;show();}
 int score(JSONObject o){return PickRules.score(s(o,"language"),o.optInt("minutes"),prefs.getInt("affinity_"+s(o,"mood"),0));}
 void show(){root=new FrameLayout(this);root.setBackground(new GradientDrawable(GradientDrawable.Orientation.TL_BR,new int[]{0xff182332,0xff090d15}));setContentView(root);label("FOR YOUR EVENING",11,0xff9bafc7,500,22,48,31).setLetterSpacing(.18f);label("Pick for tonight",26,Color.WHITE,550,40,48,54);button("Close",88,824,35,()->finish());
 button(pref("mood","Any mood"),140,48,110,()->choose("mood",new String[]{"Any mood","Light","Thrilling","Heartfelt","Adventure"}));button(limit()==0?"Any length":"Up to "+limit()+" min",140,200,110,()->time());button(pref("language","Any language"),150,352,110,()->choose("language",new String[]{"Any language","English","Tamil","French","Korean","Malayalam"}));button(pref("kind","Anything"),110,514,110,()->choose("kind",new String[]{"Anything","Film","Series","Video"}));button("Preferences",132,780,110,()->preferences());
 if(eligible.isEmpty()){current=null;label("Nothing fits just yet.",32,Color.WHITE,760,60,48,222);label("This small starter collection has no remaining matches. Change a filter, undo your last feedback, or reset your watched and hidden titles in Preferences.",17,0xffb7c4d5,700,100,48,294);button("Clear filters",160,48,407,()->{prefs.edit().remove("language").remove("limit").remove("mood").remove("kind").apply();refresh();}).requestFocus();if(lastKey!=null)button("Undo feedback",160,220,407,()->undo());return;}
 current=eligible.get(cursor%eligible.size());String id=s(current,"id");int art=getResources().getIdentifier(s(current,"art"),"drawable",getPackageName());if(art!=0){ImageView poster=new ImageView(this);poster.setImageResource(art);poster.setScaleType(ImageView.ScaleType.FIT_CENTER);poster.setBackground(bg(0xff101722,12));poster.setClipToOutline(true);put(poster,210,315,702,177);}else{label(s(current,"language").equals("French")?"Bonjour.":s(current,"mood"),30,0xffe6d8bc,215,65,697,259);label("LOCAL COLLECTION",13,0xff9bafc7,205,60,702,334);}
 String minutes=current.optInt("minutes")>0?" · ~"+current.optInt("minutes")+" min"+(s(current,"kind").equals("Series")?" / episode":""):" · Duration unverified";
 label(s(current,"provider")+"  ·  "+s(current,"language")+minutes,13,0xffb7c9dd,615,24,48,180);
 TextView title=label(s(current,"title"),31,Color.WHITE,610,89,48,215);title.setTypeface(Typeface.create("sans-serif-medium",0));title.setMaxLines(2);title.setEllipsize(android.text.TextUtils.TruncateAt.END);
 label(s(current,"why"),16,0xffc0cbd9,590,92,48,308);
 String action=s(current,"provider").equals("Prime Video")?"Open Prime Video":"Open in "+s(current,"provider");button(action,204,48,407,()->open()).requestFocus();button("Another pick",150,264,407,()->{cursor=(cursor+1)%eligible.size();show();root.findViewWithTag("another").requestFocus();}).setTag("another");button("Feedback",122,426,407,()->feedback());
 button("Why / source",144,48,467,()->source());if(lastKey!=null)button("Undo feedback",144,204,467,()->undo());
 label((cursor+1)+" / "+eligible.size()+" picks  ·  Canada snapshot: 28 Oct 2026",11,0xff91a2b8,320,22,370,480);
 root.setAlpha(0);root.animate().alpha(1).setDuration(220).start();}
 void choose(String key,String[] values){int idx=Arrays.asList(values).indexOf(pref(key,values[0]));new AlertDialog.Builder(this).setTitle(key.equals("language")?"Original language · French for practice":key.equals("kind")?"What would you like?":"Tonight’s mood").setSingleChoiceItems(values,idx,(d,w)->{prefs.edit().putString(key,values[w]).apply();d.dismiss();refresh();}).setNegativeButton("Cancel",null).show();}
 void time(){String[] labels={"Any length","Up to 30 minutes","Up to 90 minutes","Up to 120 minutes"};int[] mins={0,30,90,120};int checked=0;for(int i=0;i<mins.length;i++)if(limit()==mins[i])checked=i;new AlertDialog.Builder(this).setTitle("How much time?").setSingleChoiceItems(labels,checked,(d,w)->{prefs.edit().putInt("limit",mins[w]).apply();d.dismiss();refresh();}).setNegativeButton("Cancel",null).show();}
 void feedback(){final String id=s(current,"id"),mood=s(current,"mood");new AlertDialog.Builder(this).setTitle(s(current,"title")).setItems(new String[]{"Already watched · hide","Not tonight · skip for 12 hours","Not my thing · hide","More "+mood.toLowerCase()+" picks"},(d,w)->{if(w==3){String key="affinity_"+mood;lastKey=key;lastValue=prefs.getInt(key,0);prefs.edit().putInt(key,Math.min(5,(Integer)lastValue+1)).apply();}else{lastKey=(w==0?"watched_":w==1?"skip_":"dislike_")+id;lastValue=w==1?Long.valueOf(prefs.getLong(lastKey,0)):Boolean.valueOf(prefs.getBoolean(lastKey,false));if(w==1)prefs.edit().putLong(lastKey,System.currentTimeMillis()+12*60*60*1000L).apply();else prefs.edit().putBoolean(lastKey,true).apply();}refresh();}).setNegativeButton("Cancel",null).show();}
 void undo(){if(lastKey==null)return;SharedPreferences.Editor e=prefs.edit();if(lastValue instanceof Long)e.putLong(lastKey,(Long)lastValue);else if(lastValue instanceof Integer)e.putInt(lastKey,(Integer)lastValue);else e.putBoolean(lastKey,(Boolean)lastValue);e.apply();lastKey=null;refresh();}
 void preferences(){new AlertDialog.Builder(this).setTitle("Your picks, kept on this TV").setItems(new String[]{"Streaming services","French practice","Reset feedback","About this collection"},(d,w)->{if(w==0){String[] names={"Netflix","Prime Video","YouTube"};boolean[] values=new boolean[3];for(int i=0;i<3;i++)values[i]=prefs.getBoolean("service_"+names[i],true);new AlertDialog.Builder(this).setTitle("Services you use").setMultiChoiceItems(names,values,(dialog,n,on)->values[n]=on).setPositiveButton("Save",(dialog,n)->{SharedPreferences.Editor e=prefs.edit();for(int i=0;i<3;i++)e.putBoolean("service_"+names[i],values[i]);e.apply();refresh();}).setNegativeButton("Cancel",null).show();}else if(w==1){prefs.edit().putString("language","French").remove("limit").remove("mood").remove("kind").apply();refresh();}else if(w==2)new AlertDialog.Builder(this).setTitle("Reset your feedback?").setMessage("This clears watched titles, hidden titles, temporary skips and mood preferences. Services and filters stay as they are.").setPositiveButton("Reset",(dd,ww)->{SharedPreferences.Editor e=prefs.edit();for(String key:prefs.getAll().keySet())if(key.startsWith("watched_")||key.startsWith("dislike_")||key.startsWith("skip_")||key.startsWith("affinity_"))e.remove(key);e.apply();lastKey=null;refresh();}).setNegativeButton("Cancel",null).show();else about();}).show();}
 void about(){new AlertDialog.Builder(this).setTitle("A small, honest starting point").setMessage("12 editorial picks for your services and languages. Canadian streaming listings reviewed 28 October 2026; this is a saved snapshot, not a live catalogue. Availability can change.\n\nFrench practice means French-language content, not a beginner difficulty rating. Choose audio and subtitles inside the streaming app. YouTube may show ads.\n\nFeedback stays on this device. No account access, microphone, viewing-history tracking or recommendation server. Opening a streaming app uses that service as usual.").setPositiveButton("Done",null).show();}
 void source(){if(current==null)return;String affinity=prefs.getInt("affinity_"+s(current,"mood"),0)>0?"You asked for more "+s(current,"mood").toLowerCase()+" picks. ":"";new AlertDialog.Builder(this).setTitle("Why this pick").setMessage(affinity+"Matches your selected services and filters. English, Tamil and French receive priority; other languages stay available.\n\n"+s(current,"mood")+" · "+s(current,"kind")+"\n\nCanada listing reviewed 28 October 2026. Availability is a snapshot and may change; confirm access in the app. Runtimes are approximate.\n\n"+s(current,"source")+"\n\n"+(s(current,"provider").equals("Prime Video")?"Prime currently opens its homepage. Search for this title there.":"Title link provided. The streaming app controls profiles, availability and playback.")).setPositiveButton("Done",null).show();}
 void open(){if(current==null)return;final String pkg=s(current,"package"),url=s(current,"url"),title=s(current,"title");if(url.isEmpty()){new AlertDialog.Builder(this).setTitle("Search in Prime Video").setMessage("Search for “"+title+"”. This Fire TV version opens Prime’s homepage rather than the title page.").setPositiveButton("Open Prime Video",(d,w)->openApp(pkg)).setNegativeButton("Cancel",null).show();return;}try{startActivity(new Intent(Intent.ACTION_VIEW,Uri.parse(url)).setPackage(pkg));}catch(Exception e){new AlertDialog.Builder(this).setTitle("Title link unavailable").setMessage("You can open the app and search for “"+title+"”.").setPositiveButton("Open app",(d,w)->openApp(pkg)).setNegativeButton("Cancel",null).show();}}
 void openApp(String pkg){Intent intent=getPackageManager().getLeanbackLaunchIntentForPackage(pkg);if(intent==null)intent=getPackageManager().getLaunchIntentForPackage(pkg);try{if(intent==null)throw new IllegalStateException();startActivity(intent);}catch(Exception e){Toast.makeText(this,"This app is not available on this TV",Toast.LENGTH_LONG).show();}}
}
